    private static function jsonInput(string $key):array{$value=json_decode((string)($_POST[$key]??''),true,flags:JSON_THROW_ON_ERROR);if(!is_array($value))throw new RuntimeException('Enter a valid structured '. $key.' document.');return $value;}
    private static function tenderAmount(string $field,string $legacy):int
    {
        if(isset($_POST[$field])){$v=trim((string)$_POST[$field]);if(!preg_match('/^(0|[1-9][0-9]{0,6})(?:\.([0-9]{1,2}))?$/',$v,$m))throw new RuntimeException('Enter a money amount such as 25.00, without a currency symbol.');return (int)$m[1]*100+(int)str_pad($m[2]??'',2,'0');}
        $v=filter_var($_POST[$legacy]??'0',FILTER_VALIDATE_INT);if($v===false)throw new RuntimeException('Enter a valid amount.');return $v;
    }
    private static function command(string $a):string
    {
        $db=self::$db;$u=self::$user;$o=self::$org;$id=(int)($_POST['id']??0);
        switch($a){
            case 'venue':CommerceVenueService::venue($db,$u,$o,(string)($_POST['name']??''),(string)($_POST['location']??''));return self::url('venues');
            case 'space':$space=CommerceVenueService::space($db,$u,$o,(int)($_POST['venue']??0),(string)($_POST['name']??''));$r=self::rows('SELECT id FROM commerce_layouts WHERE organization_id=? AND space_id=?',[$o,$space]);return self::url('layout',['id'=>$r[0]['id']]);
            case 'save_layout':CommerceVenueService::save($db,$u,$o,$id,self::jsonInput('document'),(string)($_POST['expected']??''));return self::url('layout',['id'=>$id]);
            case 'publish':CommerceVenueService::publish($db,$u,$o,$id);return self::url('layout',['id'=>$id]);
            case 'clone':$id=CommerceVenueService::cloneVersion($db,$u,$o,$id);return self::url('layout',['id'=>$id]);
            case 'configure':CommerceStore::configure($db,$u,$o,$_POST);return self::url('configure');
            case 'grant':if(!CommerceAccess::local()&&($_POST['role']??'')==='tester')throw new RuntimeException('Use the explicit storefront_tester role for hosted customer preview.');CommerceStore::grant($db,$u,$o,(int)($_POST['recipient']??0),(string)($_POST['role']??''),($_POST['enabled']??'')==='1');return self::url('configure');
            case 'performance':$local=(string)($_POST['starts']??'');$_POST['dates']=[substr($local,0,10)];$_POST['times']=[substr($local,11,5)];$_POST['offsets']=[(string)($_POST['offset']??'')];return CommercePlanningExperience::command($db,$u,$o,'schedule_review');
            case 'performance_config':CommerceInventoryService::configure($db,$u,$o,$id,self::jsonInput('prices'),(string)($_POST['sales']??''),!empty($_POST['checkin']),(int)($_POST['fee']??0),(int)($_POST['tax']??0),(int)($_POST['discount']??0));return self::url('performance',['id'=>$id]);
            case 'allocate':$p=CommerceStore::row($db,'performances',$o,$id);$_POST['production']=$p['production_id'];$_POST['scope']='selected';$_POST['performances']=[$id];return CommercePlanningExperience::command($db,$u,$o,'allocation_review');
            case 'staff_discount':$amount=self::tenderAmount('discount_amount','discount_minor');CommerceBoxOfficeService::discount($db,$u,$o,$id,$amount,(string)($_POST['reason']??''));return self::url('checkout',['id'=>$id]);
            case 'ticket_change':CommerceTicketChangeService::change($db,$u,$o,(int)($_POST['ticket']??0),(string)($_POST['target']??''),(string)($_POST['reason']??''),(string)($_POST['expected_token_hash']??''));return self::url('tickets',['id'=>$id]);
            case 'void_reservation':CommerceBoxOfficeService::void($db,$u,$o,$id,(string)($_POST['reason']??''));return self::url('tickets',['id'=>$id]);
            case 'seating_mode':CommerceInventoryService::admissionMode($db,$u,$o,$id,($_POST['mode']??'')==='general_admission');return self::url('performance',['id'=>$id]);
            case 'preview_approve':CommerceStorefrontService::approve($db,$u,$o,$id,!empty($_POST['approved']));return self::url('performance',['id'=>$id]);
            case 'delivery_resend':
                $key=(string)($_POST['resend_key']??'');if(($_SESSION['commerce_delivery_forms'][$key]??0)!==$id)throw new RuntimeException('Reload this order before requesting delivery.');
                CommerceDeliveryService::resend($db,$u,$o,$id,$key,(string)($_SESSION['commerce_orders'][$o.':'.$id]??''));$_SESSION['commerce_notice']='Ticket delivery queued. Check delivery status below; this is not an email delivery confirmation.';return self::url('checkout',['id'=>$id]);
            case 'order_link':$capture=CommerceDeliveryService::prepare($db,$u,$o,$id,(string)($_SESSION['commerce_orders'][$o.':'.$id]??''),self::$base);$_SESSION['commerce_notice']='Ticket link prepared for 24 hours. Delivery is queued separately; this does not confirm an email was sent.';$_SESSION['commerce_delivery_links'][$o.':'.$id]=$capture['retrieval_path'];return self::url('checkout',['id'=>$id]);
            case 'staff_tender':
                $cash=($_POST['method']??'')==='external_terminal'?0:self::tenderAmount('cash_amount','cash_minor');
                CommerceBoxOfficeService::settle($db,$u,$o,$id,(string)($_SESSION['commerce_orders'][$o.':'.$id]??''),(string)($_POST['method']??''),$cash,(string)($_POST['provider']??''),(string)($_POST['terminal_reference']??''),!empty($_POST['confirmed']));return self::url('checkout',['id'=>$id]);
            case 'hold':
                $key=(string)($_POST['checkout_key']??'');$pending=$_SESSION['commerce_checkouts'][$key]??null;if(!$pending||(int)$pending['performance']!==$id||(self::$storefront&&!empty($pending['staff'])))throw new RuntimeException('Checkout session expired. Reload seat selection.');$seats=(array)($_POST['seats']??[]);$quantities=(array)($_POST['quantities']??[]);
                $order=!empty($pending['staff'])?CommerceBoxOfficeService::reserve($db,$u,$o,$id,$seats,$quantities,(string)($_POST['customer_name']??''),(string)($_POST['customer_email']??''),$key,$pending['token']):(!empty($pending['admissions'])?CommerceInventoryService::holdAdmissions($db,$u,$o,$id,$quantities,(string)($_POST['customer_name']??''),(string)($_POST['customer_email']??''),$key,$pending['token']):CommerceInventoryService::holdQuantities($db,$u,$o,$id,$seats,$quantities,(string)($_POST['customer_name']??''),(string)($_POST['customer_email']??''),(string)($_POST['customer_phone']??''),$key,$pending['token']));$_SESSION['commerce_orders'][$o.':'.$order['id']]=$pending['token'];return self::url('checkout',['id'=>$order['id']]);
            case 'issue_complimentary':
                $key=(string)($_POST['issuance_key']??'');$form=$_SESSION['commerce_comp_forms'][$key]??null;if(!$form||(int)$form['performance']!==$id)throw new RuntimeException('Complimentary form expired. Reload it before retrying.');
                $order=CommerceComplimentaryService::issue($db,$u,$o,$id,(array)($_POST['seats']??[]),(string)($_POST['customer_name']??''),(string)($_POST['customer_email']??''),(string)($_POST['reason']??''),$key,$form['token']);$_SESSION['commerce_orders'][$o.':'.$order['id']]=$form['token'];return self::url('checkout',['id'=>$order['id']]);
            case 'stripe_payment':$token=(string)($_SESSION['commerce_orders'][$o.':'.$id]??'');$attempt=CommerceStripeService::start($db,$u,$o,$id,$token);$order=CommerceStore::row($db,'orders',$o,$id);return in_array($order['state'],['payment_pending','exception'],true)&&$attempt['checkout_url']?$attempt['checkout_url']:self::url('checkout',['id'=>$id]);
            case 'stripe_cancel':CommerceStripeService::cancel($db,$u,$o,$id,(string)($_SESSION['commerce_orders'][$o.':'.$id]??''));return self::url('checkout',['id'=>$id]);
            case 'payment':case 'refresh_payment':case 'cancel_hold':case 'expire_simulation':
                $token=(string)($_SESSION['commerce_orders'][$o.':'.$id]??'');
                if($a==='payment'){if(self::$storefront){$order=CommerceInventoryService::own($db,$u,$o,$id,$token);CommerceStorefrontService::demandPerformance($db,$u,$o,(int)$order['performance_id']);}CommercePaymentService::start($db,$u,$o,$id,$token,(string)($_POST['scenario']??''));CommercePaymentService::refresh($db,$u,$o,$id,$token);}
                elseif($a==='refresh_payment')CommercePaymentService::refresh($db,$u,$o,$id,$token);
