    private static function admissionSelection(array $p,array $items,string $key,bool $staff,bool $open):void
    {
        $counts=[];foreach($items as $item)if(in_array($item['state'],['available','released'],true)){$seat=json_decode($item['seat_json'],true);$counts[$seat['zone']]=($counts[$seat['zone']]??0)+1;}
        echo '<h1 class="commerce-task-title">'.self::e($p['title']).'</h1><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['venue']).'</p><h3>General admission</h3><p>No assigned seats. Choose up to 12 admissions; availability is checked together when you continue. Your tester login does not create a customer account.</p>';self::pricingTerms($p);self::form('hold',['id'=>$p['id'],'checkout_key'=>$key]);
        $payload=['prices'=>json_decode($p['prices_json'],true),'counts'=>$counts,'currency'=>$p['currency'],'fee'=>(int)$p['fee_minor'],'tax'=>(int)$p['tax_basis_points'],'discount'=>(int)$p['discount_minor'],'open'=>$open];
        echo '<div data-admission-selector data-payload="'.self::e(json_encode($payload)).'">';foreach($payload['prices'] as $zone=>$categories){echo '<fieldset><legend>'.self::e($zone).' · '.(int)($counts[$zone]??0).' currently available</legend>';foreach($categories as $category=>$price)self::input('quantities['.$zone.']['.$category.']',$category.' · '.self::money($price,$p['currency']),'number',self::quantityDraft((string)$zone,(string)$category),'min="0" max="12" step="1" required inputmode="numeric" data-admission-quantity data-zone="'.self::e($zone).'" data-category="'.self::e($category).'"');echo '</fieldset>';}
        echo '<p data-admission-total role="status" aria-live="polite">Choose quantities to see the full total before payment.</p>';self::input('customer_name',$staff?'Customer name (optional)':'Purchaser name','text',self::draft('customer_name'),($staff?'':'required ').'maxlength="190" autocomplete="name"');self::input('customer_email','Test email (.invalid or approved pilot inbox'.($staff?', optional':'').')','email',self::draft('customer_email',$staff?'':'buyer@commerce.invalid'),($staff?'':'required ').'maxlength="254" autocomplete="off"');echo '<button data-admission-continue '.(!$open?'disabled':'').'>Hold admissions & review order</button></div></form>';
