        $id=(int)($_GET['id']??0);if(self::$storefront)CommerceStorefrontService::demandPerformance(self::$db,self::$user,self::$org,$id);$items=CommerceInventoryService::availability(self::$db,self::$user,self::$org,$id);$p=self::performanceContext($id);$salesOpen=CommercePerformancePolicy::problem(self::$db,self::$org,$p)===null;$prices=json_decode($p['prices_json'],true);$key=bin2hex(random_bytes(16));$retry=self::draft('checkout_key');if(isset($_SESSION['commerce_checkouts'][$retry])&&(int)$_SESSION['commerce_checkouts'][$retry]['performance']===$id)$key=$retry;$_SESSION['commerce_checkouts']??=[];if(count($_SESSION['commerce_checkouts'])>20)array_shift($_SESSION['commerce_checkouts']);$_SESSION['commerce_checkouts'][$key]??=['token'=>bin2hex(random_bytes(32)),'performance'=>$id,'staff'=>$staff,'admissions'=>$p['seating_mode']==='general_admission'];if($p['seating_mode']==='general_admission'){self::admissionSelection($p,$items,$key,$staff,$salesOpen);return;}
        echo '<div class="commerce-production-intro">';if($p['poster'])echo '<img class="commerce-artwork" alt="" src="'.self::e(self::$base.'/production-poster?id='.(int)$p['production_id']).'">';echo '<div><h1 class="commerce-task-title">'.self::e($p['title']).'</h1><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['venue']).'</p><p>'.self::e($p['location']).'</p><p>Choose seats on the map or use the seat list. Selections remain local until you continue. Accessible positions are available online.</p></div></div>';
