        if(!$salesOpen){echo '<p role="status">Sales are closed or this production is read-only. You may inspect availability.</p>';}
        $suggested=($_POST['action']??'')==='hold'?array_filter((array)($_POST['seats']??[]),'is_string'):[];$suggestionMessage='';$recommendCount=2;$recommendZone=(string)($_GET['recommend_zone']??'');if(isset($_GET['recommend_count'])&&($_SERVER['REQUEST_METHOD']??'GET')==='GET'){$requested=filter_var($_GET['recommend_count'],FILTER_VALIDATE_INT);if($requested===false||$requested<1||$requested>12)$suggestionMessage='Choose a whole number from 1 to 12 for a seat suggestion.';else{$recommendCount=$requested;try{$suggested=CommerceRecommendationService::suggest(self::$db,self::$user,self::$org,$id,$recommendCount,$recommendZone);$suggestionMessage=$suggested?'Suggested '.count($suggested).' neighboring seats. Review them and choose ticket types; they are not held yet.':'No matching group is available. Try fewer seats, a different zone or choose seats manually.';}catch(RuntimeException $e){$suggestionMessage=$e->getMessage();}}}
        echo '<details class="commerce-suggestion"'.(isset($_GET['recommend_count'])?' open':'').'><summary>Find seats together</summary><p>Suggest neighboring seats in one row and price zone. Suggestions do not reserve seats. Review accessibility descriptions and the map before continuing.</p><form method="get"><input type="hidden" name="tab" value="'.($staff?'sales':'select').'"><input type="hidden" name="id" value="'.$id.'"><div class="commerce-columns">';self::input('recommend_count','Number of seats together','number',(string)$recommendCount,'min="1" max="12" step="1" required inputmode="numeric"');echo '<label>Suggestion pricing zone<select name="recommend_zone"><option value="">Any pricing zone</option>';foreach($prices as $zone=>$categories)echo '<option value="'.self::e($zone).'" '.($recommendZone===(string)$zone?'selected':'').'>'.self::e($zone).'</option>';echo '</select></label></div><button '.(!$salesOpen?'disabled':'').'>Suggest seats together</button></form></details>';if($suggestionMessage)echo '<p role="status">'.self::e($suggestionMessage).'</p>';
        self::pricingTerms($p);echo '<details><summary>Prices by zone</summary>';foreach($prices as $zone=>$categories){echo '<p>'.self::e($zone).': ';foreach($categories as $cat=>$amount)echo self::e($cat).' '.self::money((int)$amount,$p['currency']).' · ';echo '</p>';}echo '</details>';self::form('hold',['id'=>$id,'checkout_key'=>$key]);$payload=['items'=>$items,'document'=>$p['document'],'prices'=>$prices,'currency'=>$p['currency'],'fee'=>(int)$p['fee_minor'],'tax'=>(int)$p['tax_basis_points'],'discount'=>(int)$p['discount_minor']];echo '<div data-seat-selector data-payload="'.self::e(json_encode($payload)).'"><p><a href="#commerce-seat-list-heading">Skip map and choose from the seat list</a> · <a href="#commerce-ticket-types-heading">Review ticket quantities</a></p><div class="commerce-map-toolbar">';foreach(['in'=>'Zoom in','out'=>'Zoom out'] as $k=>$label)echo '<button type="button" data-select-zoom="'.$k.'">'.$label.'</button>';foreach(['left','right','up','down'] as $k)echo '<button type="button" data-select-pan="'.$k.'">Pan '.$k.'</button>';echo '<button type="button" data-select-fit>Fit layout</button></div><div data-seat-tooltip class="commerce-seat-tooltip" id="commerce-seat-tooltip" role="tooltip" hidden></div><div class="commerce-map-wrap"><svg class="commerce-map" data-select-map role="group" aria-label="Choose seats using the map or the seat list"></svg></div><p class="commerce-legend">Available: open circle · Selected: check mark · Held: H · Sold: S · Blocked/house/allocated: X · Wheelchair positions: W. Hover or focus a seat for its number and details; touch users can use the seat list. Availability is also written beside every seat.</p><h3 id="commerce-seat-list-heading" tabindex="-1">Accessible seat list</h3><label><input type="checkbox" data-access-filter> Show wheelchair positions and companion seats only</label><div class="commerce-seat-list">';
        $items=self::orderedInventory($items,$p['document']);
        foreach($items as $i){$s=json_decode($i['seat_json'],true);$available=in_array($i['state'],['available','released'],true)&&$salesOpen;$label=$s['section_name'].' / Row '.$s['row_name'].' / Seat '.$s['label'];$companion='';if($s['companion'])foreach($items as $ci)if($ci['seat_key']===$s['companion']){$cs=json_decode($ci['seat_json'],true);$companion=$cs['section_name'].' / Row '.$cs['row_name'].' / Seat '.$cs['label'];break;}$attributes=($s['wheelchair']?' · W: Wheelchair position':'').($companion?' · Companion of '.$companion:'').($s['restricted']?' · Restricted view':'');echo '<div data-seat-row="'.self::e($i['seat_key']).'" data-accessible="'.(($s['wheelchair']||$s['companion'])?'1':'0').'"><label><input type="checkbox" data-seat-check name="seats[]" value="'.self::e($i['seat_key']).'" '.(!$available?'disabled':(in_array($i['seat_key'],$suggested,true)?'checked':'')).'>'.self::e($label.' · '.$i['state'].$attributes).'</label>';if($s['description'])echo '<p>'.self::e($s['description']).'</p>';echo '</div>';}
        echo '</div><section class="commerce-ticket-types" aria-labelledby="commerce-ticket-types-heading"><h3 id="commerce-ticket-types-heading">Ticket types</h3><p>Enter the number of each ticket type to match your selected seats. Ticket types are assigned to your seats automatically.</p>';foreach($prices as $zone=>$categories){echo '<fieldset data-ticket-zone="'.self::e($zone).'"><legend>'.(count($prices)>1?self::e($zone).' · ':'').'Ticket quantities</legend><p data-zone-count>0 selected seats · 0 tickets</p><div class="commerce-quantity-grid">';foreach($categories as $category=>$amount)echo '<label>'.self::e($category).' <span>'.self::money((int)$amount,$p['currency']).' each</span><input type="number" name="quantities['.self::e($zone).']['.self::e($category).']" data-ticket-quantity data-zone="'.self::e($zone).'" data-category="'.self::e($category).'" aria-label="'.self::e($category.' tickets'.(count($prices)>1?' in '.$zone:'' )).'" min="0" max="12" step="1" value="'.self::e(self::quantityDraft((string)$zone,(string)$category)).'" required inputmode="numeric"></label>';echo '</div></fieldset>';}echo '<p data-ticket-quantity-status role="status" aria-live="polite">Select seats, then enter your ticket quantities.</p></section><div class="commerce-summary"><strong data-selection-count>0 seats selected</strong><p data-selected-seats></p><p data-selection-total>Choose seats to see your total.</p><p data-selection-message role="status"></p></div><h3>Guest purchaser · test details only</h3>';self::input('customer_name',$staff?'Customer name (optional)':'Purchaser name','text',self::draft('customer_name'),($staff?'':'required ').'maxlength="190" autocomplete="name"');self::input('customer_email',$staff?'Synthetic email (optional, .invalid only)':'Test email (.invalid or approved pilot inbox)','email',self::draft('customer_email',$staff?'':'buyer@commerce.invalid'),($staff?'':'required ').'maxlength="254" autocomplete="off"');echo '<details><summary>Add optional phone</summary><p>Only needed when testing a box-office contact workflow. Use synthetic digits.</p>';self::input('customer_phone','Phone (optional)','tel',self::draft('customer_phone'),'maxlength="40" autocomplete="off"');echo '</details><button type="submit" data-selection-continue '.(!$salesOpen?'disabled':'').'>Hold seats & review order</button><p>All seats are held together for a limited time. Your total is confirmed by the server before payment. No customer account is created; your tester login only authorizes this preview.</p></div></form>';
    }
    private static function checkout():void
    {
        $id=(int)($_GET['id']??0);$token=(string)($_SESSION['commerce_orders'][self::$org.':'.$id]??'');$o=CommerceInventoryService::own(self::$db,self::$user,self::$org,$id,$token);CommerceInventoryService::availability(self::$db,self::$user,self::$org,(int)$o['performance_id']);$o=CommerceInventoryService::own(self::$db,self::$user,self::$org,$id,$token);$p=self::performanceContext((int)$o['performance_id']);if($p['schedule_status']!=='scheduled')echo '<p role="alert">This performance is '.self::e($p['schedule_status']).'. Existing order and financial history is retained. Contact the Box Office about next steps.</p>';echo '<h1 class="commerce-task-title">Order review</h1><p>'.self::e($p['title']).'</p><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['venue']).'</p><p>Order '.self::e($o['public_reference']).' · <strong>'.self::e($o['state']==='paid'&&CommerceComplimentaryService::isOrder(self::$db,self::$org,$id)?'complimentary issued':str_replace('_',' ',$o['state'])).'</strong></p><p>Purchaser: '.self::e($o['customer_name']).' · '.self::e($o['customer_email']).'</p><div class="commerce-table-scroll"><table><caption>Ticket price snapshot</caption><thead><tr><th>Seat</th><th>Category</th><th>Price</th></tr></thead><tbody>';foreach(self::rows('SELECT * FROM commerce_order_lines WHERE organization_id=? AND order_id=? ORDER BY id',[self::$org,$id]) as $l)echo '<tr><td>'.self::e($l['description']).'</td><td>'.self::e($l['category']).'</td><td>'.self::money((int)$l['unit_minor'],$o['currency']).'</td></tr>';echo '</tbody></table></div>';self::totals($o);if($o['state']==='held'){$remaining=self::rows('SELECT GREATEST(0,TIMESTAMPDIFF(SECOND,NOW(),expires_at)) seconds FROM commerce_orders WHERE organization_id=? AND id=?',[self::$org,$id]);echo '<p data-hold-countdown data-seconds="'.(int)$remaining[0]['seconds'].'">Hold expires in '.(int)ceil((int)$remaining[0]['seconds']/60).' minutes. Refreshing does not extend it. The server checks expiry when payment starts.</p><p data-hold-expired role="status"></p>';}elseif(in_array($o['state'],['payment_pending','exception'],true))echo '<p>Original hold deadline: '.self::e($o['expires_at']).'. Your seats remain protected until payment reconciliation is resolved.</p>';self::checkoutActions($o);
    }
    private static function totals(array $o):void
    {echo '<dl class="commerce-totals">';foreach(['subtotal'=>'Tickets','discount'=>'Discount','tax'=>'Tax','fee'=>'Order fee','total'=>'Total'] as $key=>$label)echo '<div class="'.($key==='total'?'commerce-total':'').'"><dt>'.$label.'</dt><dd>'.($key==='discount'?'−':'').self::money((int)$o[$key.'_minor'],$o['currency']).'</dd></div>';echo '</dl>';}
    private static function checkoutActions(array $o):void
    {
        $id=(int)$o['id'];$staffSale=CommerceBoxOfficeService::evidence(self::$db,self::$org,$id);
        if($staffSale&&$staffSale['method'])echo '<p><strong>'.self::e($staffSale['method']==='cash'?'Cash receipt confirmed by staff':'External terminal payment recorded by staff').'</strong> · Not API verified'.($staffSale['method']==='cash'?' · Change due '.self::money((int)$staffSale['change_due_minor'],$o['currency']):' · '.self::e($staffSale['terminal_provider'].' / '.$staffSale['terminal_reference'])).'</p>';
        if($o['state']==='held'){
            if(self::$storefront)CommerceStorefrontService::demandPerformance(self::$db,self::$user,self::$org,(int)$o['performance_id']);
            if($staffSale&&self::can('discount')){self::form('staff_discount',['id'=>$id]);echo '<details><summary>Apply authorized discount</summary>';self::input('discount_amount','Ticket discount ('.$o['currency'].')','text',number_format((int)$o['discount_minor']/100,2,'.',''),'inputmode="decimal" required');self::input('reason','Discount authorization reason','text','','required maxlength="500"');echo '<button>Apply discount & recalculate total</button></details></form>';}if($staffSale&&self::can('sell')){self::form('staff_tender',['id'=>$id]);echo '<h3>Record counter payment</h3><p>Sandbox practice only. Do not take real payment. Confirm receipt only after reviewing the exact amount. An external reference is staff evidence, not provider verification.</p><label>Payment method<select name="method"><option value="cash">Cash</option><option value="external_terminal">External terminal</option></select></label>';self::input('cash_amount','Cash received ('.$o['currency'].')','text',number_format((int)$o['total_minor']/100,2,'.',''),'inputmode="decimal" data-cash-amount');echo '<p data-change-due data-total-minor="'.(int)$o['total_minor'].'" data-currency="'.self::e($o['currency']).'" role="status">Change due: '.self::money(0,$o['currency']).'</p>';self::input('provider','External terminal provider','text','','maxlength="100"');self::input('terminal_reference','Terminal transaction reference (never card details)','text','','maxlength="190"');echo '<label><input type="checkbox" name="confirmed" value="1" required> I confirm the stated tender was received in this synthetic exercise.</label><button>Confirm tender & issue tickets</button></form>';}
            if(CommerceStripeProvider::configured()&&getenv('COMMERCE_STRIPE_CHECKOUT_ENABLED')==='1'&&(CommerceAccess::local()||Auth::hasRole(self::$user,'administrator'))){self::form('stripe_payment',['id'=>$id]);echo '<h3>Stripe test checkout</h3><p>Use Stripe test cards only. Card details stay on Stripe. Seats remain protected until the provider confirms a final result.</p><button>Continue to Stripe test checkout</button></form>';}self::form('payment',['id'=>$id]);echo '<h3>Simulate payment</h3><p>No card details. No financial transaction.</p><label>Test outcome<select name="scenario"><option value="success">Successful payment</option><option value="declined">Declined payment</option><option value="canceled">Canceled payment</option><option value="delayed">Delayed confirmation (15 seconds)</option><option value="timeout">Timeout / uncertain result</option></select></label><button>Run simulated payment</button></form><div class="commerce-actions">';self::form('expire_simulation',['id'=>$id]);echo '<button>Simulate expired checkout</button></form>';self::form('cancel_hold',['id'=>$id]);echo '<button>Cancel checkout & release seats</button></form></div>';
        }elseif(in_array($o['state'],['payment_pending','exception','refund_pending'],true)){
            echo '<h3>'.($o['state']==='exception'?'Payment needs review':($o['state']==='refund_pending'?'Refund is pending':'Waiting for payment confirmation')).'</h3><p>Your seats remain protected. Do not begin a replacement purchase while this attempt is unresolved. Check the provider result below. If it remains uncertain, ask the Commerce administrator to review this order; do not pay again.</p>';self::form('refresh_payment',['id'=>$id]);echo '<button>Check authoritative payment confirmation</button></form>';if(CommerceStripeService::attempt(self::$db,self::$org,$id)&&$o['state']!=='refund_pending'){self::form('stripe_cancel',['id'=>$id]);echo '<button>Request safe cancellation at Stripe</button></form>';}
        }elseif($o['state']==='paid'){
            $comp=CommerceComplimentaryService::isOrder(self::$db,self::$org,$id);echo '<h3>'.($comp?'Complimentary tickets issued':($staffSale&&$staffSale['method']?'Box Office tickets issued':(CommerceStripeService::attempt(self::$db,self::$org,$id)?'Stripe test purchase confirmed':'Simulated purchase confirmed'))).'</h3>'.($comp?'<p>Zero-price staff-authorized settlement. No payment was processed.</p>':'').'<p>Your sandbox tickets are ready. Each QR contains only an unpredictable admission token. These tickets have no real-world validity.</p>';$token=(string)($_SESSION['commerce_orders'][self::$org.':'.$id]??'');$p=self::performanceContext((int)$o['performance_id']);foreach(CommerceReceiptService::ownedTickets(self::$db,self::$user,self::$org,$id,$token) as $t)echo '<article class="commerce-ticket"><h3>'.self::e($p['title']).'</h3><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['venue']).'</p><p>'.self::e($t['description'].' · '.$t['category'].' · '.$t['state']).'</p>'.($t['state']==='valid'&&$p['schedule_status']==='scheduled'?CommerceReceiptService::qr($t['token']):'').'<details><summary>Manual ticket code</summary><code class="commerce-token">CC1:'.self::e($t['token']).'</code></details></article>';self::deliveryStatus($o);echo CommerceReceiptService::preview(OrganizationBranding::fromEnvironment(),$o,$p);echo '<button type="button" onclick="window.print()">Print tickets / Save as PDF</button>';self::form('order_link',['id'=>$id]);echo '<button>Create secure 24-hour order link</button></form>';if(isset($_SESSION['commerce_delivery_links'][self::$org.':'.$id]))echo '<p><a href="'.self::e($_SESSION['commerce_delivery_links'][self::$org.':'.$id]).'">Open secure ticket retrieval link</a> · expires 24 hours after creation</p>';if(!$comp&&!($staffSale&&$staffSale['method'])){self::form('refresh_payment',['id'=>$id]);echo '<button>Check payment confirmation again</button></form>';}
        }else echo '<p>This checkout is '.self::e($o['state']).'. No new payment can start. Select seats again to retry with a new order.</p>';
        echo '<p><a href="'.self::e(self::url($staffSale?'sales':'select',['id'=>$o['performance_id']])).'">'.($staffSale?'Start next Box Office sale':'Back to seat selection').'</a></p>';
    }

    private static function performancePicker(string $tab):int
    {
        $id=(int)($_GET['id']??0);echo '<form method="get"><input type="hidden" name="tab" value="'.self::e($tab).'"><label>Performance<select name="id"><option value="">Choose performance</option>';foreach(self::rows('SELECT c.*,p.title FROM commerce_performances c JOIN productions p ON p.id=c.production_id WHERE c.organization_id=? ORDER BY c.starts_at DESC',[self::$org]) as $p){if(in_array($tab,['sales','complimentary'],true)&&CommercePerformancePolicy::problem(self::$db,self::$org,$p))continue;echo '<option value="'.(int)$p['id'].'" '.($id===(int)$p['id']?'selected':'').'>'.self::e($p['title'].' · '.CommercePerformancePolicy::label($p)).'</option>';}echo '</select></label><button>Open performance</button></form>';return$id;
    }
    private static function checkin():void
    {
        CommerceAccess::demand(self::$db,self::$user,self::$org,'checkin');echo '<h2>Box office & check-in</h2><p>Online verification is required. Camera support depends on the browser and secure context. Keyboard-wedge scanners can enter the code and press Enter. No offline multi-device admission is supported.</p>';$id=self::performancePicker('checkin');if(!$id)return;$p=self::performanceContext($id);$a=CommerceTicketService::attendance(self::$db,self::$user,self::$org,$id);echo '<h3>'.self::e($p['title']).'</h3><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['venue']).' · Check-in '.($p['checkin_enabled']?'enabled':'closed').'</p><p role="status">Admitted '.(int)$a['admitted'].' of '.(int)$a['valid_count'].' valid tickets · '.(int)$a['issued'].' issued including revoked/refunded.</p>';self::form('checkin',['id'=>$id]);self::input('scan','Scan or paste admission code','text','','required autocomplete="off" autocapitalize="off" spellcheck="false" data-scan');echo '<button>Verify & admit ticket</button><div data-camera><button type="button" data-camera-start>Start QR camera</button><button type="button" data-camera-stop hidden>Stop camera</button><p data-camera-status role="status">Camera is off. Manual and keyboard scanners work without camera permission.</p><video data-camera-video playsinline muted hidden></video></div></form><h3>Manual order lookup</h3>';self::form('door_lookup',['id'=>$id]);self::input('reference','Sandbox order reference','text','','required pattern="[a-f0-9]{32}" autocomplete="off"');echo '<button>Find admission tickets</button></form>';
        $reference=(string)($_GET['reference']??'');if($reference==='')return;$tickets=CommerceTicketService::lookup(self::$db,self::$user,self::$org,$id,$reference);if(!$tickets)echo '<p>No admission tickets found for this reference and performance.</p>';foreach($tickets as $t){echo '<section class="commerce-record"><h3>'.self::e($t['description']).'</h3><p>'.self::e($t['category'].' · '.$t['state']).' · '.($t['checked_in_at']?'Admitted '.self::e($t['checked_in_at']):'Not admitted').'</p>';if($p['schedule_status']==='scheduled'&&$p['checkin_enabled']&&$t['state']==='valid'&&!$t['checked_in_at']){self::form('checkin',['id'=>$id,'scan'=>'CC1:'.$t['token']]);echo '<button>Admit '.self::e($t['description']).'</button></form>';}if(self::can('reverse')&&$t['checked_in_at']){self::form('reverse',['id'=>$id,'ticket'=>$t['id'],'reference'=>$reference]);self::input('reason','Reversal reason','text','','required maxlength="500"');echo '<button>Reverse admission</button></form>';}echo '</section>';}
    }
    private static function complimentary():void
    {
        CommerceAccess::demand(self::$db,self::$user,self::$org,'complimentary');echo '<h2>Complimentary tickets</h2><p>Issue zero-price sandbox admissions with a required reason. No payment attempt, fee or tax is created. A sandbox confirmation is queued in capture mode by default. Held, sold, blocked and house-reserved seats remain protected.</p>';$id=self::performancePicker('complimentary');if(!$id)return;$p=self::performanceContext($id);CommerceStore::organization(self::$db,self::$org,true);if($problem=CommercePerformancePolicy::problem(self::$db,self::$org,$p)){echo '<p role="alert">'.self::e($problem).'</p>';return;}echo '<h3>'.self::e($p['title']).'</h3><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['venue']).'</p><p>Complimentary issuance requires a published, scheduled, future performance with open sales. Existing production lifecycle restrictions still apply.</p>';
        $key=bin2hex(random_bytes(16));$_SESSION['commerce_comp_forms']??=[];if(count($_SESSION['commerce_comp_forms'])>=20)array_shift($_SESSION['commerce_comp_forms']);$_SESSION['commerce_comp_forms'][$key]=['performance'=>$id,'token'=>bin2hex(random_bytes(32))];
        self::form('issue_complimentary',['id'=>$id,'issuance_key'=>$key]);echo '<fieldset><legend>Choose up to 12 complimentary seats</legend><div class="commerce-seat-list">';foreach(self::orderedInventory(CommerceInventoryService::inventory(self::$db,self::$org,$id),$p['document']) as $i){$seat=json_decode($i['seat_json'],true);$eligible=in_array($i['state'],['available','released','complimentary'],true);echo '<label><input type="checkbox" name="seats[]" value="'.self::e($i['seat_key']).'" '.(!$eligible?'disabled':'').'>'.self::e($seat['section_name'].' / '.$seat['row_name'].' / '.$seat['label'].' · '.$i['state'].($seat['wheelchair']?' · Wheelchair position':'').($seat['companion']?' · Companion seat':'')).'</label>';if($seat['description'])echo '<p>'.self::e($seat['description']).'</p>';}echo '</div></fieldset>';self::input('customer_name','Recipient name','text','','required maxlength="190" autocomplete="off"');self::input('customer_email','Synthetic recipient email ending in .invalid','email','recipient@commerce.invalid','required maxlength="254" autocomplete="off"');echo '<label>Reason for complimentary admission<textarea name="reason" required maxlength="500" rows="3"></textarea></label><p>All selected seats are issued together. The resulting order totals '.self::money(0,$p['currency']).' and retains an audit record.</p><button>Issue complimentary sandbox tickets</button></form>';
    }

    private static function orders():void
    {
        CommerceAccess::demand(self::$db,self::$user,self::$org,'report');echo '<h2>Orders & reconciliation</h2><form method="get"><input type="hidden" name="tab" value="orders">';self::input('reference','Full sandbox order reference','text',(string)($_GET['reference']??''),'required pattern="[a-f0-9]{32}"');echo '<button>Find order</button></form>';$reference=(string)($_GET['reference']??'');
        if($reference!==''){$o=CommerceTicketService::reportOrder(self::$db,self::$user,self::$org,$reference);if(!$o){echo '<p>No matching order.</p>';return;}$id=(int)$o['id'];$stripeAttempt=CommerceStripeService::attempt(self::$db,self::$org,$id);echo '<p><a href="'.self::e(self::url('tickets',['id'=>$id])).'">Print, reissue or relocate tickets</a></p>';echo '<h3>Order '.self::e($o['public_reference']).'</h3><p>'.self::e($o['customer_name'].' · '.$o['customer_email'].' · '.$o['state']).'</p>';self::totals($o);
            if(!$stripeAttempt&&$o['state']==='exception'&&self::can('refund')){self::form('refund_unfulfillable',['id'=>$id,'reference'=>$reference]);echo '<h3>Unfulfillable confirmed simulation</h3><p>Only for a definite simulator success with no issued tickets on a performance that cannot accept sales. Unknown results must first be reconciled. No real funds move.</p>';self::input('reason','Simulated return / reconciliation reason','text','','required maxlength="500"');echo '<button>Simulate full return without issuing tickets</button></form>';}if(in_array($o['state'],['payment_pending','exception','refund_pending'],true)){self::form('staff_refresh',['id'=>$id,'reference'=>$reference]);echo '<button>Reconcile authoritative provider result</button></form>';if(!$stripeAttempt&&self::can('configure')){self::form('resolve',['id'=>$id,'reference'=>$reference]);echo '<h3>Local simulator evidence</h3><p>Only for an uncertain timeout simulation. This does not contact a real provider or move money.</p><label>Definitive test outcome<select name="outcome"><option value="succeeded">Confirmed success</option><option value="failed">Confirmed failure</option><option value="canceled">Confirmed cancellation</option></select></label>';self::input('reason','Reconciliation evidence / reason','text','','required maxlength="500"');echo '<button>Record simulator evidence & reconcile</button></form>';}}
            if(CommerceComplimentaryService::isOrder(self::$db,self::$org,$id))echo '<p>Complimentary admission · zero-price staff settlement · no payment provider attempt.</p>';
            if(self::can('refund')&&($o['state']==='paid'||($stripeAttempt&&in_array($o['state'],['exception','refund_pending'],true)))){self::form('refund',['id'=>$id,'reference'=>$reference]);$tender=CommerceBoxOfficeService::evidence(self::$db,self::$org,$id);if($tender&&$tender['method'])echo '<p>Connect cannot refund cash or an external terminal. Record the return only after it has been completed separately.</p><label><input type="checkbox" name="staff_return_confirmed" value="1" required> I confirm the tender was returned in this synthetic exercise.</label>';self::input('reason',CommerceComplimentaryService::isOrder(self::$db,self::$org,$id)?'Complimentary cancellation reason':($stripeAttempt?'Stripe test refund / retry reason':'Full simulated refund reason'),'text','','required maxlength="500"');echo '<button>'.(CommerceComplimentaryService::isOrder(self::$db,self::$org,$id)?'Cancel complimentary order & release seats':($stripeAttempt?'Request / reconcile full Stripe test refund':'Refund full sandbox order')).'</button></form>';}
            foreach(self::rows('SELECT t.*,l.description,l.category FROM commerce_tickets t JOIN commerce_order_lines l ON l.order_id=t.order_id AND l.seat_key=t.seat_key AND l.organization_id=t.organization_id WHERE t.organization_id=? AND t.order_id=?',[self::$org,$id]) as $t){echo '<section class="commerce-record"><h3>'.self::e($t['description']).'</h3><p>'.self::e($t['category'].' · '.$t['state']).' · '.($t['checked_in_at']?'Admitted':'Not admitted').'</p>';if(self::can('refund')&&$t['state']==='valid'&&!$t['checked_in_at']){self::form('revoke',['id'=>$id,'ticket'=>$t['id'],'reference'=>$reference]);self::input('reason','Revocation reason','text','','required maxlength="500"');echo '<button>Revoke ticket without releasing sold seat</button></form>';}echo '</section>';}
            echo '<details><summary>Order audit trail</summary>';foreach(self::rows("SELECT a.action,a.actor_user_id,a.created_at,a.detail_json FROM commerce_audit a WHERE a.organization_id=? AND ((a.entity_type='order' AND a.entity_id=?) OR (a.entity_type='ticket' AND EXISTS(SELECT 1 FROM commerce_tickets t WHERE t.organization_id=a.organization_id AND t.id=a.entity_id AND t.order_id=?))) ORDER BY a.id",[self::$org,$id,$id]) as $event)echo '<p class="commerce-record">'.self::e($event['created_at'].' · '.$event['action'].' · staff #'.$event['actor_user_id']).'<br>'.self::e($event['detail_json']).'</p>';echo '</details>';
        }else{
            echo '<h3>Recent sandbox orders</h3><div class="commerce-records">';foreach(self::rows('SELECT public_reference,state,total_minor,currency,created_at FROM commerce_orders WHERE organization_id=? ORDER BY id DESC LIMIT 50',[self::$org]) as $o)echo '<div class="commerce-record"><a href="'.self::e(self::url('orders',['reference'=>$o['public_reference']])).'">'.self::e($o['public_reference']).'</a> · '.self::e($o['state']).' · '.self::money((int)$o['total_minor'],$o['currency']).' · '.self::e($o['created_at']).'</div>';echo '</div>';
        }
    }

